bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
test "$(docker ps --filter label=com.docker.compose.project=gace-createvdobot --filter label=com.docker.compose.service=videobot-poll -q | wc -l)" -eq 1 || exit 62
docker exec -i "$cid" node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import {openCreatorEditor,editCreatorDraft,creatorEditorPanel} from '/opt/videobot/src/telegram/creatorUi.mjs';
const owner='10455';
let d=openCreatorEditor({sellerId:owner});
d=editCreatorDraft(d,{type:'captionTitle',text:'プレビュー確認'});
d=editCreatorDraft(d,{type:'paidVideo',media:{fileId:'testing_video123'}});
d=editCreatorDraft(d,{type:'thumbnail',media:{fileId:'testing_photo123'}});
d=editCreatorDraft(d,{type:'sample',media:{fileId:'testing_sample123',durationSeconds:22}});
d=editCreatorDraft(d,{type:'preset',stars:50});
const existing=openCreatorEditor({sellerId:owner,existing:{id:'fixture123',sellerId:owner,revision:1,title:'プレビュー確認',priceStars:50,paidVideo:{fileId:'testing_video123'},thumbnail:{fileId:'testing_photo123'},sample:{fileId:'testing_sample123',durationSeconds:22}}});
for(const [mode,draft,guide,action] of [['create',d,'📝 登録方法','entry:register'],['edit',existing,'📝 編集方法','edit:save']]){
 const p=creatorEditorPanel(draft,10,'editor');
 assert.match(p.text,new RegExp(guide));
 assert.ok(p.text.indexOf(guide)>p.text.indexOf('有料本編：'));
 assert.doesNotMatch(p.text,/販売手数料|管理費|30%|70%|取り分|引き出し可能|実払出/);
 assert.equal(p.reply_markup.inline_keyboard.flat().filter(b=>String(b.callback_data||'').startsWith(action)).length,1);
 const forbidden=mode==='edit'?'entry:register':'edit:save';
 assert.ok(p.reply_markup.inline_keyboard.flat().every(b=>!String(b.callback_data||'').startsWith(forbidden)));
 assert.ok(!p.entities||p.entities.every(e=>e.offset>=0&&e.offset+e.length<=p.text.length));
}
console.log('VIDEO_PREVIEW_REGISTER_EDIT_PRODUCTION_READBACK=PASS');
NODE
docker exec "$cid" node --check /opt/videobot/src/telegram/creatorUi.mjs || exit 63
echo VIDEO_PREVIEW_SINGLE_POLLER_AND_SOURCE_OK=PASS
